async function init(){try{const response=await fetch('/api/state');if(!response.ok)throw new Error('无法连接本地服务。');state=await response.json();render();}catch(error){app.innerHTML=`<div class="fatal"><span class="brand">small<span>.</span>plan</span><h1>计划还在，连接暂时断开了。</h1><p>${esc(error.message)} 请确认 Small Plan 服务正在运行，然后重新载入。</p><button class="btn primary" id="reload-app">重新载入</button></div>`;$('#reload-app').addEventListener('click',()=>location.reload());}}
